    idempotency key key
    retry_class reconcilable
    reconcile by find_draft_invoice
    compensation delete_draft_invoice

  tool delete_draft_invoice(id: DraftId, key: Text) -> Receipt<DraftId>
    critical
    idempotency key key
    retry_class idempotent
}

